-- ТРКИ — bổ sung câu thiếu + sửa đáp án sai theo PDF gốc (26/11/2026, chủ dự án duyệt).
-- Đã áp dụng lên Supabase qua hàm tạm (cùng nội dung bên dưới) bằng tài khoản admin; file này là bản ghi, chạy lại an toàn
-- (phần đã áp dụng bị bỏ qua). Kết quả lần chạy: sửa 211 câu, ẩn 2 câu, thêm/khôi phục 86 câu, 15 đề, 1594 câu khớp parts.
--  * Sửa đáp án/phương án/đề theo khoá PDF: Minobr A2 (tipovoj_test_a2.pdf), B2 (Типовой тест. ТРКИ-2.pdf),
--    C1 (ТРКИ-III.pdf), C2 (ТРКИ-IV.pdf); chuyên đề Златоуст C1 Тест 10/14/17 («Тесты, тесты, тесты...»).
--  * Ẩn: TRKI_A2_MINOBR_READ_Q110 (bản sao câu từ vựng 110), TRKI_C2_MINOBR_READ_Q001 (câu tự luận mang nhầm phương án).
--  * Thêm/khôi phục: Minobr A2/B2/C1/C2 (khoá PDF; câu Nghe chưa có âm thanh — bổ sung sau), chuyên đề Златоуст
--    B2-17, C1-9/10/14/17 (khoá sách), VNZh Lịch sử 15–20 & Pháp luật 20 (khoá PDF), SPbSU A2#2 Đọc 6, B1#1 Từ 77,
--    C1#2 Từ 49 (khoá PDF), ТПУ #2 (33 câu) & #3 (5 câu) — sách không có khoá, người soạn giải (cần giáo viên duyệt).
--  * A2 câu 83 giữ theo khoá PDF («получил») theo quyết định của chủ dự án.
-- Dừng (không ghi gì) nếu vị trí câu ngân hàng ↔ parts lệch trước hoặc sau khi áp dụng.

create or replace function private.rusi_tmp_positions()
returns table (question_id uuid, code text, test_code text, test_id text, part_idx int, q_idx int, sub_test text,
               order_index int, matched boolean, v jsonb)
language sql stable set search_path to '' as $$
  with ordered as (
    select q.id, q.code, q.test_code, q.options, q.sub_test, q.order_index,
           row_number() over (partition by q.test_code order by
             case q.sub_test when 'lexis_grammar' then 1 when 'grammar' then 1 when 'reading' then 2
                             when 'listening' then 3 when 'writing' then 4 when 'speaking' then 5 else 9 end,
             q.order_index, q.id) - 1 as pos
      from public.trki_question_bank q where q.is_published
  ), flat as (
    select t.id as test_id, t.code as test_code, (p.ord - 1)::int as part_idx, (j.ord - 1)::int as q_idx,
           row_number() over (partition by t.id order by p.ord, j.ord) - 1 as pos, j.v
      from public.trki_tests t,
           jsonb_array_elements(t.parts) with ordinality p(v, ord),
           jsonb_array_elements(coalesce(p.v -> 'questions', '[]'::jsonb)) with ordinality j(v, ord)
  )
  select o.id, o.code, o.test_code, f.test_id, f.part_idx, f.q_idx, o.sub_test, o.order_index,
         (f.v -> 'options' = o.options), f.v
    from ordered o join flat f on f.test_code = o.test_code and f.pos = o.pos
$$;

-- Ghi parts mới từ tmp_slots (test_id, part_idx, k1, k2, k3, code, v) cho các đề trong p_tests
create or replace function private.rusi_tmp_write_parts(p_tests text[])
returns void language plpgsql set search_path to '' as $$
begin
  with rebuilt as (
    select t.id,
           (select jsonb_agg(
                     case when exists (select 1 from tmp_slots x where x.test_id = t.id and x.part_idx = p.ord - 1)
                          then jsonb_set(p.v, '{questions}', (
                                 select jsonb_agg(x.v order by x.k1, x.k2, x.k3)
                                   from tmp_slots x where x.test_id = t.id and x.part_idx = p.ord - 1))
                          else p.v end
                     order by p.ord)
              from jsonb_array_elements(t.parts) with ordinality p(v, ord)) as new_parts
      from public.trki_tests t where t.id = any (p_tests)
  )
  update public.trki_tests t
     set parts = r.new_parts, sections = r.new_parts,
         part1 = coalesce(r.new_parts -> 0, '{}'::jsonb), part2 = coalesce(r.new_parts -> 1, '{}'::jsonb),
         part3 = coalesce(r.new_parts -> 2, '{}'::jsonb), part4 = coalesce(r.new_parts -> 3, '{}'::jsonb),
         part5 = coalesce(r.new_parts -> 4, '{}'::jsonb), updated_at = now()
    from rebuilt r where r.id = t.id and t.parts is distinct from r.new_parts;
end $$;

create or replace function private.rusi_fill_apply(p_ops jsonb)
returns jsonb
language plpgsql
set search_path to 'public', 'pg_temp'
as $fn$
declare v_n int; v_m int; v_bad int; v_dup int; v_hid int; v_sub int; v_bank int; v_parts int;
        v_edits int := 0; v_unpub int := 0; v_tests text[];
begin
  create temporary table tmp_edit on commit drop as
  select * from jsonb_to_recordset(coalesce(p_ops -> 'edits', '[]'::jsonb)) as x(
    code text, prompt text, options jsonb, correct_index int, correct_indices int[], question_type text,
    explanation text, correct_answer text, official_key text);
  create temporary table tmp_unpub on commit drop as
  select jsonb_array_elements_text(coalesce(p_ops -> 'unpublish', '[]'::jsonb)) as code;
  create temporary table tmp_add on commit drop as
  select * from jsonb_to_recordset(coalesce(p_ops -> 'adds', '[]'::jsonb)) as x(
    seq int, test_code text, code text, anchor text, mode text, hidden boolean, sub_test text, prompt text,
    options jsonb, correct_index int, correct_indices int[], question_type text, explanation text, topic text,
    passage text, official_key text, correct_answer text);

  -- điền phần thiếu của câu sửa từ dữ liệu hiện có
  update tmp_edit e set options = coalesce(e.options, q.options), prompt = coalesce(e.prompt, q.prompt)
    from public.trki_question_bank q where q.code = e.code and q.is_published;
  update tmp_edit set correct_index = correct_indices[1] where correct_indices is not null;
  update tmp_edit set correct_answer = coalesce(correct_answer, case when correct_indices is not null
           then (select string_agg(options ->> i, ' / ' order by i) from unnest(correct_indices) i)
           else options ->> correct_index end)
   where true;
  update tmp_edit set official_key = (array['А','Б','В','Г','Д','Е','Ж','З','И','К','Л'])[correct_index + 1]
   where official_key is null and correct_indices is null;
  update tmp_edit set explanation = case when correct_indices is not null
           then 'Đáp án chính thức (chọn tất cả phương án đúng): ' || (select string_agg((array['А','Б','В','Г','Д','Е'])[i + 1] || '. ' || (options ->> i), '; ' order by i) from unnest(correct_indices) i)
           else 'Đáp án chính thức: (' || official_key || ') ' || correct_answer end
   where explanation is null;

  -- bỏ phần đã áp dụng (idempotent)
  delete from tmp_add a using public.trki_question_bank q where q.code = a.code and q.is_published;
  delete from tmp_unpub u where not exists (select 1 from public.trki_question_bank q where q.code = u.code and q.is_published);
  delete from tmp_edit e using public.trki_question_bank q
   where q.code = e.code and q.is_published and q.options = e.options and q.correct_index = e.correct_index
     and q.prompt = coalesce(e.prompt, q.prompt) and q.correct_indices is not distinct from e.correct_indices
     and q.explanation is not distinct from e.explanation;

  -- ===== A. Sửa câu đang xuất bản (tại chỗ) + gỡ câu sai =====
  create temporary table tmp_pos on commit drop as
  select p.* from private.rusi_tmp_positions() p
   where p.test_code in (select q.test_code from public.trki_question_bank q
                          where q.code in (select code from tmp_edit union select code from tmp_unpub));
  select count(*) into v_n from tmp_edit e where not exists (select 1 from tmp_pos p where p.code = e.code);
  if v_n > 0 then raise exception 'Dừng: % câu sửa không ở trạng thái xuất bản', v_n; end if;
  select count(*) into v_bad from tmp_pos where not matched;
  if v_bad > 0 then raise exception 'Dừng: % câu (đề cần sửa) lệch vị trí parts', v_bad; end if;
  select count(*) into v_n from tmp_edit
   where options is null or jsonb_array_length(options) < 2 or correct_index is null
      or correct_index < 0 or correct_index >= jsonb_array_length(options);
  if v_n > 0 then raise exception 'Dừng: % câu sửa có options/correct_index không hợp lệ', v_n; end if;

  update public.trki_question_bank q
     set prompt = coalesce(e.prompt, q.prompt), options = e.options, correct_index = e.correct_index,
         correct_indices = e.correct_indices, question_type = coalesce(e.question_type, 'multiple_choice'),
         correct_answer = e.correct_answer, explanation = e.explanation, updated_at = now()
    from tmp_edit e where q.code = e.code and q.is_published;
  get diagnostics v_edits = row_count;

  create temporary table tmp_slots on commit drop as
  select p.test_id, p.part_idx, p.q_idx as k1, 1 as k2, 0 as k3, p.code,
         case when e.code is null then p.v
              else (p.v - 'multi') || jsonb_strip_nulls(jsonb_build_object(
                     'q', coalesce(e.prompt, p.v ->> 'q'), 'options', e.options, 'a', e.correct_index,
                     'ex', e.explanation, 'correct_answer', e.correct_answer, 'official_key', e.official_key,
                     'multi', case when e.correct_indices is not null then true end)) end as v
    from tmp_pos p left join tmp_edit e on e.code = p.code
   where not exists (select 1 from tmp_unpub u where u.code = p.code);

  select array_agg(distinct test_id) into v_tests from tmp_pos;
  if v_tests is not null then perform private.rusi_tmp_write_parts(v_tests); end if;
  update public.trki_question_bank set is_published = false, updated_at = now() where code in (select code from tmp_unpub);
  get diagnostics v_unpub = row_count;
  drop table tmp_slots;
  drop table tmp_pos;

  -- ===== B. Thêm câu mới / khôi phục câu ẩn =====
  create temporary table tmp_pos on commit drop as
  select * from private.rusi_tmp_positions() where test_code in (select test_code from tmp_add);

  update tmp_add a set anchor = (select p.code from tmp_pos p where p.test_code = a.test_code and p.sub_test = a.sub_test
                                 order by p.part_idx, p.q_idx limit 1)
   where a.mode = 'first';

  create temporary table tmp_slot_new on commit drop as
  select a.*, p.test_id, p.part_idx, p.q_idx as anchor_q, p.v as anchor_v
    from tmp_add a join tmp_pos p on p.code = a.anchor and p.test_code = a.test_code;

  select count(*), (select count(*) from tmp_slot_new) into v_n, v_m from tmp_add;
  if v_m <> v_n then raise exception 'Dừng: % / % câu không tìm thấy câu neo đã xuất bản', v_n - v_m, v_n; end if;
  select count(*) into v_bad from tmp_pos where not matched;
  if v_bad > 0 then raise exception 'Dừng: % câu của đề cần thêm lệch vị trí parts', v_bad; end if;
  select count(*) into v_dup from tmp_add a join public.trki_question_bank q on q.code = a.code where not a.hidden;
  if v_dup > 0 then raise exception 'Dừng: % code mới đã tồn tại', v_dup; end if;
  select count(*) into v_hid from tmp_add a where a.hidden
     and not exists (select 1 from public.trki_question_bank q where q.code = a.code and q.test_code = a.test_code and not q.is_published);
  if v_hid > 0 then raise exception 'Dừng: % dòng ẩn không tồn tại', v_hid; end if;
  select count(*) into v_sub from tmp_slot_new s join tmp_pos p on p.code = s.anchor where p.sub_test <> s.sub_test;
  if v_sub > 0 then raise exception 'Dừng: % câu khác sub_test với câu neo', v_sub; end if;

  update public.trki_question_bank q
     set prompt = s.prompt, options = s.options, correct_index = s.correct_index, correct_indices = s.correct_indices,
         question_type = s.question_type, correct_answer = s.correct_answer, explanation = s.explanation,
         passage = coalesce(s.passage, q.passage), topic = coalesce(s.topic, q.topic), is_published = true, updated_at = now()
    from tmp_slot_new s where s.hidden and q.code = s.code;

  insert into public.trki_question_bank (code, test_code, test_id, level, sub_test, part_number, question_type, topic,
    difficulty, prompt, passage, options, correct_index, correct_indices, correct_answer, explanation, points,
    order_index, is_published, is_pro_only)
  select s.code, s.test_code, n.test_id, n.level, s.sub_test, n.part_number, s.question_type, coalesce(s.topic, n.topic),
         n.difficulty, s.prompt, s.passage, s.options, s.correct_index, s.correct_indices, s.correct_answer, s.explanation,
         n.points, n.order_index, true, n.is_pro_only
    from tmp_slot_new s join public.trki_question_bank n on n.code = s.anchor
   where not s.hidden;

  create temporary table tmp_slots on commit drop as
  select p.test_id, p.part_idx, p.q_idx as k1, 1 as k2, 0 as k3, p.code, p.v
    from tmp_pos p where p.test_id in (select test_id from tmp_slot_new)
  union all
  select s.test_id, s.part_idx, s.anchor_q, case when s.mode = 'first' then 0 else 2 end, s.seq, s.code,
         jsonb_strip_nulls(jsonb_build_object(
           'q', s.prompt, 'options', s.options, 'a', s.correct_index, 'ex', s.explanation,
           'correct_answer', s.correct_answer, 'topic', coalesce(s.topic, s.anchor_v ->> 'topic'),
           'passage', s.passage, 'official_key', s.official_key,
           'multi', case when s.correct_indices is not null then true end))
    from tmp_slot_new s;

  select array_agg(distinct test_id) into v_tests from tmp_slot_new;
  if v_tests is not null then
    perform private.rusi_tmp_write_parts(v_tests);
    with fin as (
      select x.code, row_number() over (partition by x.test_id order by x.part_idx, x.k1, x.k2, x.k3) as rn
        from tmp_slots x
    )
    update public.trki_question_bank q set order_index = f.rn, updated_at = now()
      from fin f where q.code = f.code and q.is_published and q.order_index is distinct from f.rn;
  end if;

  -- ===== C. Kiểm tra cuối + số câu trong tên =====
  select array_agg(distinct t.id) into v_tests from public.trki_tests t
   where t.code in (select test_code from tmp_add union
                    select q.test_code from public.trki_question_bank q where q.code in (select code from tmp_edit union select code from tmp_unpub));
  if v_tests is null then return jsonb_build_object('applied', 0); end if;

  select count(*) filter (where not matched) into v_bad from private.rusi_tmp_positions() where test_id = any (v_tests);
  select count(*) into v_bank from public.trki_question_bank q join public.trki_tests t on t.code = q.test_code
   where q.is_published and t.id = any (v_tests);
  select count(*) into v_parts from public.trki_tests t, jsonb_array_elements(t.parts) p,
         jsonb_array_elements(coalesce(p -> 'questions', '[]'::jsonb)) j where t.id = any (v_tests);
  if v_bad > 0 or v_bank <> v_parts then
    raise exception 'Dừng: sau khi áp dụng lệch % câu (ngân hàng %, parts %)', v_bad, v_bank, v_parts;
  end if;

  with rebuilt as (
    select t.id,
           (select jsonb_agg(
                     case when (p.v ->> 'vi') ~ '\(\d+ câu\)' and jsonb_array_length(coalesce(p.v -> 'questions', '[]'::jsonb)) > 0
                          then jsonb_set(p.v, '{vi}', to_jsonb(regexp_replace(p.v ->> 'vi', '\(\d+ câu\)',
                                 '(' || jsonb_array_length(p.v -> 'questions') || ' câu)')))
                          else p.v end
                     order by p.ord)
              from jsonb_array_elements(t.parts) with ordinality p(v, ord)) as new_parts
      from public.trki_tests t where t.id = any (v_tests)
  )
  update public.trki_tests t
     set parts = r.new_parts, sections = r.new_parts,
         part1 = coalesce(r.new_parts -> 0, '{}'::jsonb), part2 = coalesce(r.new_parts -> 1, '{}'::jsonb),
         part3 = coalesce(r.new_parts -> 2, '{}'::jsonb), part4 = coalesce(r.new_parts -> 3, '{}'::jsonb),
         part5 = coalesce(r.new_parts -> 4, '{}'::jsonb), updated_at = now()
    from rebuilt r where r.id = t.id and t.parts is distinct from r.new_parts;

  update public.trki_tests t
     set title = regexp_replace(t.title, '\(\d+ câu\)', '(' || x.nq || ' câu)'), updated_at = now()
    from (select t2.id, (select sum(jsonb_array_length(coalesce(p -> 'questions', '[]'::jsonb)))
                           from jsonb_array_elements(t2.parts) p) as nq
            from public.trki_tests t2 where t2.id = any (v_tests)) x
   where x.id = t.id and t.title ~ '\(\d+ câu\)' and (substring(t.title from '\((\d+) câu\)'))::int <> x.nq;

  return jsonb_build_object('edited', v_edits, 'unpublished', v_unpub, 'added', (select count(*) from tmp_slot_new),
                            'tests', cardinality(v_tests), 'bank', v_bank, 'parts', v_parts);
end;
$fn$;
revoke all on function private.rusi_fill_apply(jsonb) from public, anon, authenticated;

select private.rusi_fill_apply($ops${"edits": [{"code": "TRKI_A2_MINOBR_Q001", "prompt": "Этот мужчина молодой, а этот - … .", "options": ["старший", "старый", "старинный"], "correct_index": 1, "explanation": "Đáp án chính thức: (Б) старый"}, {"code": "TRKI_A2_MINOBR_Q002", "prompt": "Джон читает ... без словаря.", "options": ["по-русски", "русский", "русский язык"], "correct_index": 0, "explanation": "Đáp án chính thức: (А) по-русски"}, {"code": "TRKI_A2_MINOBR_READ_Q001", "prompt": "В пятницу и субботу библиотека не работает. Вы можете взять книги в библиотеке ... .", "options": ["в понедельник", "в среду и субботу", "в пятницу"], "correct_index": 0, "explanation": "Đáp án chính thức: (А) в понедельник"}, {"code": "TRKI_A2_MINOBR_READ_Q003", "prompt": "Всем студентам необходимо получить в деканате студенческие билеты. Все студенты должны ... .", "options": ["купить билеты на самолёт", "взять студенческий билет", "получить студенческую визу"], "correct_index": 1, "explanation": "Đáp án chính thức: (Б) взять студенческий билет"}, {"code": "TRKI_A2_MINOBR_READ_Q004", "prompt": "Расписание занятий по русскому языку висит на втором этаже. Вы хотите посмотреть расписание, поэтому Вам нужно ... .", "options": ["спуститься на первый этаж", "пойти на второй этаж", "подняться на третий этаж"], "correct_index": 1, "explanation": "Đáp án chính thức: (Б) пойти на второй этаж"}, {"code": "TRKI_A2_MINOBR_READ_Q005", "prompt": "Пожалуйста, не курите в коридоре.", "options": ["В коридоре нельзя курить.", "Курить можно только в коридоре.", "Все курят в коридоре."], "correct_index": 0, "explanation": "Đáp án chính thức: (А) В коридоре нельзя курить."}, {"code": "TRKI_A2_MINOBR_READ_Q006", "prompt": "Мой друг отдыхает.", "options": ["Он говорит только по-китайски.", "Будьте добры, говорите медленнее.", "Прошу вас, не разговаривайте так громко."], "correct_index": 2, "explanation": "Đáp án chính thức: (В) Прошу вас, не разговаривайте так громко."}, {"code": "TRKI_A2_MINOBR_READ_Q007", "prompt": "Здесь так холодно.", "options": ["Закройте, пожалуйста, окно.", "Включите, пожалуйста, свет.", "Не курите, пожалуйста, здесь."], "correct_index": 0, "explanation": "Đáp án chính thức: (А) Закройте, пожалуйста, окно."}, {"code": "TRKI_A2_MINOBR_Q034", "options": ["эта машина", "этой машины", "эту машину", "на этой машине"], "correct_index": 0}, {"code": "TRKI_A2_MINOBR_Q035", "options": ["эта машина", "этой машины", "эту машину", "на этой машине"], "correct_index": 1}, {"code": "TRKI_A2_MINOBR_LIST_Q001", "prompt": "Прослушайте фразу. Найдите идентичную информацию в представленных вариантах.", "options": ["Она приехала из Америки.", "Она любит Америку.", "Она родилась в Америке."], "correct_index": 0}, {"code": "TRKI_A2_MINOBR_LIST_Q002", "prompt": "Прослушайте фразу. Найдите идентичную информацию в представленных вариантах.", "options": ["Он много занимается.", "Он уже хорошо изучил русский язык.", "Ему нравится русский язык."], "correct_index": 1}, {"code": "TRKI_A2_MINOBR_LIST_Q003", "prompt": "Прослушайте фразу. Найдите идентичную информацию в представленных вариантах.", "options": ["Он стал совсем другим.", "Он такой же, каким был раньше.", "Я хорошо знаю мой родной город."], "correct_index": 0}, {"code": "TRKI_A2_MINOBR_LIST_Q005", "prompt": "Прослушайте фразу. Найдите идентичную информацию в представленных вариантах.", "options": ["Я знаю Диму давно.", "Дима - немолодой человек.", "Дима старше, чем я."], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_READ_Q002", "correct_index": 2}, {"code": "TRKI_B2_MINOBR_READ_Q021", "correct_index": 2}, {"code": "TRKI_B2_MINOBR_READ_Q024", "options": ["заставил героев усомниться в подлинности своих чувств", "привел героев к пониманию того, что не стоит задумываться о будущем", "дал героям подлинное понимание счастья и сложности жизни"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_LIST_Q004", "correct_index": 1}, {"code": "TRKI_B2_MINOBR_LIST_Q014", "correct_index": 2}, {"code": "TRKI_B2_MINOBR_LIST_Q019", "correct_index": 1}, {"code": "TRKI_B2_MINOBR_LIST_Q020", "correct_index": 2}, {"code": "TRKI_B2_MINOBR_LIST_Q024", "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q001", "prompt": "На заседании Совета с кратким сообщением ... ученый секретарь Смирнова.", "options": ["выступили", "выступал", "выступила", "выступил"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q003", "prompt": "До отхода поезда ... полчаса, успеем выпить по чашечке кофе.", "options": ["остались", "остаются", "осталось", "останутся"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q004", "prompt": "К концу XX столетия большинство уже не ... к книге как основному источнику знаний.", "options": ["обращается", "обращаются", "обратятся", "обращались"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q005", "prompt": "В библиотеке современной поэзии, которую я начал собирать, ... около 500 книг.", "options": ["насчитывались", "насчитываются", "насчитывается", "насчитается"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q006", "prompt": "Приведенные Вами доказательства представляются мне ... .", "options": ["неубедительные", "не убедительно", "не убедительны", "неубедительными"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q007", "prompt": "Мы пришли на встречу с писателем ... и поэтому смогли занять места поближе к сцене.", "options": ["первых", "первыми", "первый", "первым"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q008", "prompt": "Все то, что рассказал в своем выступлении этот выдающийся политик, ... .", "options": ["интересное и новое", "интересно и ново", "интересный и новый", "интересен и нов"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q009", "prompt": "Как ни ... эта задача, мы постараемся ее решить.", "options": ["трудная", "очень трудная", "трудна", "трудно"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q010", "prompt": "Саша, ты можешь не ... , твоя помощь нам не понадобится.", "options": ["приходить", "прийти"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q011", "prompt": "Я очень рад: домашнее задание сегодня можно не ... .", "options": ["сдавать", "сдать"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q012", "prompt": "На факультете открылась новая столовая, и теперь мы успеваем быстро ... во время перерыва.", "options": ["обедать", "пообедать"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q013", "prompt": "Мы не должны ... друг с другом. Давайте все обсудим спокойно.", "options": ["спорить", "поспорить"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q014", "prompt": "Стоило мне ... свет, и все увидели блеск звезд на ночном небе.", "options": ["выключать", "выключить"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q015", "prompt": "Без разрешения врача ванну не ... . Для вас это опасно.", "options": ["принимать", "принять"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q020", "prompt": "Чего же вы ждете? ... писать тест. Времени осталось мало.", "options": ["Начинайте", "Начните"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q021", "prompt": "Не ... я вчера на свидание, мы бы не поссорились.", "options": ["опаздывай", "опоздай"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q024", "prompt": "Общественному транспорту здесь ... запрещено.", "options": ["останавливаться", "остановиться"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q025", "prompt": "С вашим предложением трудно не ... . Оно полностью учитывает все наши замечания.", "options": ["соглашаться", "согласиться"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q027", "prompt": "Растущая конкуренция влияет ... качества продукции.", "options": ["для улучшения", "улучшением", "улучшение", "на улучшение"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q030", "prompt": "Сотрудник опоздал на совещание и долго извинялся ... .", "options": ["своих коллег", "свои коллеги", "у своих коллег", "перед своими коллегами"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q031", "prompt": "... вы вполне можете поступить в аспирантуру.", "options": ["В ваших способностях", "С вашими способностями", "От ваших способностей", "О ваших способностях"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q035", "prompt": "Я был очень удивлен ... своих коллег.", "options": ["замечаний", "замечания", "замечаниях", "замечаниями"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q040", "prompt": "«До встречи на финише ... », — сказали нам спортсмены, когда мы брали у них интервью. (Из газет)", "options": ["после суток", "за сутки", "на сутки", "через сутки"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q046", "prompt": "Как известно, ... жидкость испаряется.", "options": ["в нагревании", "с нагреванием", "при нагревании", "после нагревания"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q053", "prompt": "В современной технике используются закономерности, ... еще в прошлом веке.", "options": ["открывающие", "открываемые", "открывшие", "открытые"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q054", "prompt": "В Эрмитаже открылась выставка, ... все этапы реставрации и восстановления картины Рембрандта «Даная».", "options": ["отраженная", "отражающая", "отражаемая", "отразив"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q056", "prompt": "... , мой приятель совершенно неожиданно отказался от работы.", "options": ["Бросая начатые эксперименты", "Бросив начатые эксперименты", "Бросавший начатые эксперименты", "Бросающий начатые эксперименты"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q057", "prompt": "Всесторонне обсудив тему, ... .", "options": ["работа была начата", "было произведено начало работ", "можно начинать работу", "работа началась"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q060", "prompt": "В книгу вошли высказывания, принадлежащие известным политикам.", "options": ["которые принадлежали известным политикам", "которые должны принадлежать известным политикам", "которые принадлежат известным политикам", "которые будут принадлежать известным политикам"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q065", "prompt": "Реконструкция исторического центра города, которую предложил губернатор, осуществляется по определенному плану.", "options": ["предлагаемая губернатором", "предлагающаяся губернатором", "предложенная губернатором", "предлагавшаяся губернатором"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q069", "prompt": "Встав пораньше, ты сможешь закончить рисунок при дневном свете.", "options": ["Так как встанешь пораньше", "Когда встанешь пораньше", "Если встанешь пораньше", "Хотя встанешь пораньше"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q074", "prompt": "После того как прочитаете книгу, подумайте, что хотел сказать автор.", "options": ["Читая книгу", "Читавшие книгу", "Прочитав книгу", "Прочитывая книгу"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q076", "prompt": "Сначала Игорь показался мне скучным человеком, ... очень скоро я поняла, что это не так.", "options": ["и", "а", "но", "да"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q077", "prompt": "Наконец выпал первый снег, ... в лесу стало необычно тихо и чисто.", "options": ["хотя", "но", "да", "и"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q078", "prompt": "Студент подготовил для научной конференции доклад, ... рассказал о проведенном анализе.", "options": ["перед которым", "с которым", "в котором", "на котором"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q079", "prompt": "Вчера я была на встрече с известным ученым, ... книгами я давно уже была знакома.", "options": ["с какими", "с чьими", "с которыми", "с которого"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q080", "prompt": "Наступили такие замечательные дни, ... бывают в Петербурге только в самом начале лета.", "options": ["какие", "чьи", "если", "когда"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q081", "prompt": "Перед входом в лекторий висело объявление, ... .", "options": ["чтобы завтра лекция была в 14.00", "будет ли завтра лекция в 14.00", "что завтра лекция будет в 14.00", "в котором лекция будет завтра в 14.00"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q083", "prompt": "Приглашения удалось получить ... , кто подал заявки заранее.", "options": ["тем", "теми", "о тех", "с теми"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q090", "prompt": "Кто знает, ... Виталий перестал бывать у нас.", "options": ["если", "отчего", "потому что", "раз"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q091", "prompt": "Попробуй другое пирожное, ... это тебе не нравится.", "options": ["когда", "поэтому", "из-за чего", "раз"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q092", "prompt": "... было уже поздно и артисты устали, зрители не расходились и продолжали аплодировать.", "options": ["Благодаря тому что", "Так как", "Несмотря на то что", "Если"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q093", "prompt": "... отключили электричество, мы не смогли закончить работу.", "options": ["Благодаря тому что", "Из того что", "Из-за того что", "Для того чтобы"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q102", "prompt": "Преступника можно найти по ... пальцев.", "options": ["опечаткам", "отпечаткам", "перепечаткам", "допечаткам"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q103", "prompt": "Природа и сегодня загадывает ученым много ... .", "options": ["задач", "задумок", "заданий", "загадок"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q105", "prompt": "... науки занимают важное место при подготовке специалистов в вузе.", "options": ["Общие", "Общественные", "Общинные", "Общительные"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q107", "prompt": "Все замолчали, услышав такой ... отказ.", "options": ["решительный", "решающий", "решаемый", "решивший"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q112", "prompt": "По дороге домой купи к ужину ... сладенького.", "options": ["кое-какие из", "сколько-нибудь из", "какое-нибудь из", "что-нибудь из"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q113", "prompt": "Я не ... написать сочинение на такую отвлеченную тему.", "options": ["люблю", "умею", "знаю", "могу"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q115", "prompt": "Никогда не знаешь, куда она смотрит: она всегда ... в темных очках.", "options": ["носит", "несет", "идет", "ходит"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q116", "prompt": "Маша ... все книжные магазины города, но так и не нашла нужную книгу.", "options": ["обошла", "прошла", "перешла", "зашла"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q117", "prompt": "Мне ... помочь моему другу, так как он долго болел, очень отстал и нуждался в помощи.", "options": ["повезло", "посчастливилось", "удалось", "пришлось"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q118", "prompt": "Перед тем как пить, это вино лучше ... .", "options": ["охладеть", "охладить", "холодеть", "холодать"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q119", "prompt": "При получении гонорара автор должен ... в ведомости.", "options": ["вписаться", "расписаться", "подписаться", "записаться"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q122", "prompt": "Я должен ... к своим новым соседям.", "options": ["всмотреться", "посмотреть", "присмотреться", "присмотреть"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q126", "prompt": "С 1742 года М.В.Ломоносов стал ... Академии наук в Санкт-Петербурге.", "options": ["преподаватель", "преподавателем", "с преподавателем", "для преподавателя"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q127", "prompt": "Тем самым научная подготовка молодого ученого признавалась ... .", "options": ["основательной и достаточной", "основательная и достаточная", "основательна и достаточна", "основательно и достаточно"], "correct_index": 0}, {"code": "TRKI_B2_MINOBR_Q129", "prompt": "Многие его работы считались ... в науке того времени.", "options": ["новое слово", "новым словом", "новым словам", "новыми словами"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q130", "prompt": "... были, к примеру, некоторые его опыты в области химии.", "options": ["Интересное и уникальное", "Интересно и уникально", "Интересен и уникален", "Интересными и уникальными"], "correct_index": 3}, {"code": "TRKI_B2_MINOBR_Q131", "prompt": "Занимаясь науками, не забывал Ломоносов и поэзию. Именно благодаря поэзии имя Ломоносова стало ... императрице Елизавете Петровне.", "options": ["известное", "известно", "известен", "известный"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q136", "prompt": "Прошу разрешить мне командировку в Новосибирск ... неделю", "options": ["на", "в", "сроком на", "на срок"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q141", "prompt": "В книге известного литературоведа Ю.Л.Прокушева ... большой, во многом ранее не известный архивный материал.", "options": ["содержался", "содержится", "содержит", "будет содержаться"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q142", "prompt": "В ней подробно ... важнейшие вехи жизни и творческого пути Сергея Есенина.", "options": ["рассматривают", "рассматриваются", "будут рассматриваться", "рассматривались"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q144", "prompt": "В книге ... важнейшие черты, свойственные стихам Есенина.", "options": ["раскрывают", "раскрыли", "будут раскрываться", "раскрываются"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q145", "prompt": "Книга Ю.Л.Прокушева ... всем, кто интересуется жизнью и творчеством великого русского поэта.", "options": ["адресовалась", "адресуется", "будет адресоваться", "будет адресована"], "correct_index": 1}, {"code": "TRKI_B2_MINOBR_Q147", "prompt": "Многие государственные организации ... жителям районов, пострадавших ...", "options": ["помогли", "содействовали", "оказали помощь", "оказали внимание"], "correct_index": 2}, {"code": "TRKI_B2_MINOBR_Q149", "prompt": "Наш комитет намерен ... среди жителей микрорайона в поддержку молодого перспективного кандидата.", "options": ["советовать голосовать", "просить голосовать", "агитировать голосовать", "вести агитацию"], "correct_index": 3}, {"code": "TRKI_C1_MINOBR_Q001", "correct_index": 1}, {"code": "TRKI_C1_MINOBR_Q002", "options": ["задумался", "задумывался", "задумался бы", "задумается"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q007", "options": ["Разрешайте", "Разрешили бы", "Разрешите", "Разрешали бы"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q010", "options": ["полезен", "полезный", "полезно", "полезным"], "correct_index": 1}, {"code": "TRKI_C1_MINOBR_Q013", "prompt": "Андрей перед своим первым выступлением на сцене выглядел ... .", "options": ["растерявшийся и взволнованный", "растерян и взволнован", "растерявшимся и взволнованным"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q032", "options": ["капризам", "из-за капризов", "к капризам", "для капризов"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q033", "options": ["непослушному ребенку", "непослушным ребенком", "для непослушного ребенка", "у непослушного ребенка"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q034", "prompt": "Неожиданно грузовик съехал с дороги и очутился прямо ... .", "options": ["за дом", "в доме", "на дом", "с домом"], "correct_index": 1}, {"code": "TRKI_C1_MINOBR_Q036", "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q039", "prompt": "В годы второй мировой войны миллионы людей погибли ... .", "options": ["во имя свободы и мира", "из-за свободы и мира", "для свободы и мира", "в силу свободы и мира"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q040", "options": ["из образов", "с образами", "образами", "образы"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q044", "options": ["для строительства", "от строительства", "по строительству", "при строительстве"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q045", "prompt": "Виктор «стрелой» пролетел по перрону и вскочил на подножку отходящего поезда. (На какой вопрос отвечает выделенное слово?)", "options": ["зачем?", "почему?", "где?", "как?"], "correct_index": 3}, {"code": "TRKI_C1_MINOBR_Q046", "prompt": "Роман забежал ко мне за конспектом «к экзамену». (На какой вопрос отвечает выделенное выражение?)", "options": ["где?", "каким?", "почему?", "как?"], "correct_index": 1}, {"code": "TRKI_C1_MINOBR_Q047", "prompt": "«Разгоряченный быстрой ходьбой», он сначала не почувствовал ни мелко моросящего дождя, ни холодного ветра. (На какой вопрос отвечает выделенное выражение?)", "options": ["почему?", "где?", "зачем?", "когда?"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q048", "prompt": "Взглянув вверх, в темноту, Андрей поднял воротник пальто и «не торопясь» пошел через площадь. (На какой вопрос отвечает выделенное выражение?)", "options": ["когда?", "почему?", "зачем?", "как?"], "correct_index": 3}, {"code": "TRKI_C1_MINOBR_Q050", "prompt": "Мне нужно купить подарок отцу на день рождения, и я знаю, что купить.", "options": ["Я решил кое-что купить.", "Я решил купить что-нибудь.", "Я решил что-то купить.", "Надо бы что-то купить."], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q056", "correct_index": 3}, {"code": "TRKI_C1_MINOBR_Q057", "options": ["что", "чтобы", "словно", "будто"], "correct_index": 1}, {"code": "TRKI_C1_MINOBR_Q058", "prompt": "Страх, ... он опять опоздает, не покидал меня.", "options": ["потому что", "как будто", "что", "так как"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q059", "prompt": "Сестру не оставляет надежда, ... ей все-таки удастся в этом году поступить в институт.", "options": ["если", "что", "когда", "ли"], "correct_index": 1}, {"code": "TRKI_C1_MINOBR_Q060", "prompt": "Каждый день я вижу, ... зеленеет и расцветает мой сад.", "options": ["пока", "когда", "если", "как"], "correct_index": 3}, {"code": "TRKI_C1_MINOBR_Q062", "prompt": "... мне необходимо длительное лечение, прошу разрешить мне перенести сроки сдачи проекта.", "options": ["Благодаря тому что", "Когда", "Пока", "В связи с тем что"], "correct_index": 3}, {"code": "TRKI_C1_MINOBR_Q063", "prompt": "... вы так волнуетесь, придется отложить ваше выступление.", "options": ["Раз", "Несмотря на то что", "Хотя", "Чтобы"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q064", "prompt": "Стоило ему начать говорить, ... все замолкали и внимательно прислушивались.", "options": ["когда", "после того как", "как", "прежде чем"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q065", "prompt": "... развиваются наука и техника, меняются представления людей о мироздании.", "options": ["Как", "По мере того как", "После того как", "Пока не"], "correct_index": 1}, {"code": "TRKI_C1_MINOBR_Q066", "prompt": "Необходимо как можно скорее закончить ремонт, ... ударили холода.", "options": ["пока", "когда", "пока не", "как только"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q068", "prompt": "— Смотря что вы хотите облить, — ответил он. — Хотите облить скатерть, наклоняйте от себя, а ... хотите облить свою одежду, то к себе.", "options": ["как", "если", "хотя", "так как"], "correct_index": 1}, {"code": "TRKI_C1_MINOBR_Q072", "options": ["мы обязательно успели бы на поезд", "мы не успели на поезд", "мы все равно не успели бы на поезд", "мы непременно успели на поезд"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q073", "prompt": "Как ни уговаривали мы Илью, ... .", "options": ["он все равно не пошел с нами на концерт", "он все-таки шел с нами на концерт", "ему все равно не пойти с нами на концерт", "он обязательно пойдет с нами на концерт"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q076", "prompt": "К решению той или иной научной проблемы следует подходить, имея ... актуальности, необходимости предстоящего исследования.", "options": ["основу", "базу", "обоснование", "основание"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q077", "prompt": "После смерти родителей детям досталось небольшое ... .", "options": ["наследство", "наследие", "последствие", "следствие"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q078", "options": ["дружная", "дружественная", "дружеская"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q079", "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q080", "prompt": "Произведения этого писателя ... по своему стилю и образной символике.", "options": ["характерны", "интересны", "типизированы", "обильны"], "correct_index": 1}, {"code": "TRKI_C1_MINOBR_Q081", "options": ["простирается", "тянется", "возвышается", "размещается"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q082", "prompt": "Она работает учителем, поэтому всегда ... громко, четко, медленно.", "options": ["выговаривает", "проговаривает", "говорит", "наговаривает"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q083", "prompt": "Не успел я ... на воскресную поездку за город, как погода испортилась и начались проливные дожди.", "options": ["настроиться", "пристроиться", "расстроиться", "перестроиться"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q084", "prompt": "В новом районе на берегу ручья, который берет начало в одном из городских парков, ... живописный сквер.", "options": ["разбили", "выбили", "забили", "отбили"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q086", "prompt": "Благодаря своевременной помощи рана на руке охотника быстро ... .", "options": ["зажила", "пережила", "выжила", "ожила"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q087", "prompt": "Мама попросила старшую дочь ... суп из супницы по тарелкам.", "options": ["влить", "слить", "пролить", "разлить"], "correct_index": 3}, {"code": "TRKI_C1_MINOBR_Q088", "prompt": "Наша фирма теперь называется иначе, поэтому нам пришлось ... вывеску.", "options": ["сменить", "отменить", "подменить", "применить"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q089", "prompt": "Мне навсегда ... мосты над Невой, словно парящие в воздухе.", "options": ["вспомнились", "припомнились", "запомнились"], "correct_index": 2}, {"code": "TRKI_C1_MINOBR_Q090", "prompt": "Раньше это был жилой дом, а теперь его почти полностью ... , и туда переехал банк.", "options": ["перестроили", "пристроили", "выстроили", "надстроили"], "correct_index": 0}, {"code": "TRKI_C1_MINOBR_Q091", "prompt": "У меня еще нет опыта в воспитании детей. Часто я ... себя:", "options": ["упрашиваю", "спрашиваю", "расспрашиваю", "допрашиваю"], "correct_index": 1}, {"code": 